design.css:
/* Marquee — a streaming-service look, copied from measured references of the live site and its TV app.
   #141414, white, one red, Inter as the stand-in for the service's own sans. Web values are the live site's
   computed styles at 1600 px; the TV block sizes from a 1920 canvas (--u). */

/* ── Shell: an 80 px bar of pill destinations, a gradient over the page that turns solid black once the
   page scrolls (.4 s). izumi's 32 px window band stays above the row. ── */
:scope { --mq-red: #e50914; }

:scope:not([data-surface="tv"]) { --theme-top-row: 80px; }

:scope:not([data-surface="tv"]) [data-slot="nav.top"] { gap: 6px !important; padding-left: 60px !important; padding-right: 60px !important; border: 0 !important; background-color: transparent !important; background-image: linear-gradient(rgba(0, 0, 0, 0.8), rgba(0, 0, 0, 0)) !important; transition: background-color 0.4s linear; }

:scope:not([data-surface="tv"]) [data-slot="nav.top"][data-scrolled] { background-color: #000 !important; }

:scope:not([data-surface="tv"]) [data-slot="nav.top"] > [data-part="nav.item"] { height: 41px; padding: 10px 16px !important; border-radius: 24px !important; background: transparent; color: rgba(255, 255, 255, 0.7) !important; font-size: 16px !important; font-weight: 400 !important; line-height: 21px; transition: background-color 0.2s ease, color 0.2s ease; }

:scope:not([data-surface="tv"]) [data-slot="nav.top"] > [data-part="nav.item"]:nth-child(1 of [data-part="nav.item"]:not([data-dest="search"])) { margin-left: 18px; }

:scope:not([data-surface="tv"]) [data-slot="nav.top"] > [data-part="nav.item"]:hover { background: rgba(255, 255, 255, 0.1) !important; color: #fff !important; }

:scope:not([data-surface="tv"]) [data-slot="nav.top"] > [data-part="nav.item"][data-active] { background: rgba(255, 255, 255, 0.2) !important; color: #fff !important; font-weight: 500 !important; }

/* Text pills; the search destination is the round icon at the right end of the bar. */
:scope:not([data-surface="tv"]) [data-slot="nav.top"] > [data-part="nav.item"]:not([data-dest="search"]) [data-part="nav.item.icon"] { display: none; }

:scope:not([data-surface="tv"]) [data-slot="nav.top"] > [data-part="nav.item"][data-dest="search"] { order: 1; width: 40px; height: 40px; padding: 0 !important; justify-content: center; border-radius: 50% !important; background: transparent !important; color: #fff !important; }

:scope:not([data-surface="tv"]) [data-slot="nav.top"] > [data-part="nav.item"][data-dest="search"] [data-part="nav.item.label"] { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

:scope:not([data-surface="tv"]) [data-slot="nav.top"] > [data-part="nav.item"][data-dest="search"] [data-part="nav.item.icon"] svg { width: 24px; height: 24px; }

:scope:not([data-surface="tv"]) [data-slot="nav.top"] > [data-part="nav.action"] { order: 2; margin-left: 6px; width: 40px !important; height: 40px !important; border-radius: 50% !important; background: transparent !important; color: #fff !important; }

:scope:not([data-surface="tv"]) [data-slot="nav.top"] > [data-part="nav.action"]:hover, :scope:not([data-surface="tv"]) [data-slot="nav.top"] > [data-part="nav.item"][data-dest="search"]:hover { background: rgba(255, 255, 255, 0.1) !important; }

:scope:not([data-surface="tv"]) [data-slot="nav.top"] > [data-part="nav.action"] svg { width: 24px; height: 24px; }

:scope:not([data-surface="tv"]) [data-slot="nav.top"] > [data-part="nav.action"][data-action="account"] img { width: 32px; height: 32px; border-radius: 4px; }

/* While a video plays in a window the bar sits over it: solid black, the izumi mark alone. */
:scope:not([data-surface="tv"]):has([data-slot="watch"]) [data-slot="nav.top"] { background: #000 !important; background-image: none !important; }

:scope:not([data-surface="tv"]):has([data-slot="watch"]) [data-slot="nav.top"] > :is([data-part="nav.item"], [data-part="nav.action"], [data-part="nav.menu"]) { display: none !important; }

/* ── Home: the ambient glow of the billboard's art from the very top of the page, under the clear bar
   (on the page, not on Home, which starts below the bar). ── */
:scope:not([data-surface="tv"]) [data-slot="page"]:has([data-slot="home"]) { background-image: radial-gradient(130% 900px at 50% -8px, color-mix(in srgb, rgb(var(--hero-ambient-rgb, 20 20 20)) 40%, #141414) 20%, rgba(20, 20, 20, 0) 65%); background-repeat: no-repeat; }

/* Billboard: an inset card 60 px from both edges, 8 px under the bar, radius 24, the art cover with the
   trailer fading in over it, the copy bottom-left with 40 px padding. */
:scope:not([data-surface="tv"]) [data-slot="home.hero"][data-variant="template"] { height: calc(100vh - var(--theme-top-bar) - 79px) !important; min-height: 420px; margin: 8px 60px 36px !important; border-radius: 24px; box-shadow: rgba(0, 0, 0, 0.45) 10px 20px 32px; }

:scope:not([data-surface="tv"]) [data-slot="home.hero"][data-variant="template"]::after { content: ""; position: absolute; inset: 0; z-index: 3; border: 2px solid rgba(255, 255, 255, 0.04); border-radius: 24px; pointer-events: none; }

:scope:not([data-surface="tv"]) [data-slot="home.hero"][data-state="loading"] { margin: 8px 60px 36px !important; border-radius: 24px; background: transparent !important; box-shadow: none; }

:scope:not([data-surface="tv"]) [data-slot="home.hero"][data-state="loading"]::after { display: none; }

:scope:not([data-surface="tv"]) [data-slot="home.hero"][data-state="loading"] .skeloader { opacity: 0; }

:scope:not([data-surface="tv"]) [data-part="mq.billboard"]::after { background: linear-gradient(90deg, rgba(0, 0, 0, 0.6) 0%, rgba(0, 0, 0, 0) 60%), linear-gradient(0deg, rgba(0, 0, 0, 0.5) 0%, rgba(0, 0, 0, 0.1) 35%, rgba(0, 0, 0, 0) 70%) !important; }

[data-part="mq.art"] img { transform: none !important; }

[data-part="hero.video"] iframe { scale: 1.002; }

:scope:not([data-surface="tv"]) [data-part="hero.mute"] { display: grid !important; place-items: center; width: 32px !important; height: 32px !important; padding: 0 !important; top: 40px !important; right: 40px !important; border: 0 !important; border-radius: 50% !important; background: rgba(128, 128, 128, 0.4) !important; color: #fff !important; -webkit-backdrop-filter: none !important; backdrop-filter: none !important; }

:scope:not([data-surface="tv"]) [data-part="hero.mute"] svg { width: 16px; height: 16px; }

:scope:not([data-surface="tv"]) [data-part="mq.copy"] { padding-bottom: 40px !important; }

:scope:not([data-surface="tv"]) [data-part="mq.logo"] { height: 192px; margin-bottom: 16px; }

:scope:not([data-surface="tv"]) :is([data-part="mq.logo"], [data-part="mq.title"]) { transform-origin: left bottom; transition: transform 1s ease; }

:scope:not([data-surface="tv"]) [data-slot="home.hero"]:has([data-part="hero.video"][data-state="playing"]) :is([data-part="mq.logo"], [data-part="mq.title"]) { transform: scale(0.65); }

:scope:not([data-surface="tv"]) [data-part="mq.logo"] img { object-position: left bottom; }

:scope:not([data-surface="tv"]) [data-part="mq.title"] { max-width: 576px; margin-bottom: 16px; line-height: 1.1; letter-spacing: -0.02em; text-shadow: none !important; }

:scope:not([data-surface="tv"]) [data-part="mq.attrs"] { margin-bottom: 12px; color: #fff; line-height: 24px; }

[data-part="mq.dot"] { color: rgba(255, 255, 255, 0.4); }

[data-part="mq.dot"]:first-child { display: none; }

[data-part="mq.count"] { white-space: pre; }

[data-part="mq.age"] { display: inline-grid; place-items: center; min-width: 24px; height: 24px; padding: 0 5px; border: 1px solid rgba(255, 255, 255, 0.4); border-radius: 3px; line-height: 1; }

:scope:not([data-surface="tv"]) [data-part="mq.desc"] { display: grid !important; grid-template-rows: 1fr; margin-bottom: 24px; transition: grid-template-rows 1s ease, margin 1s ease, opacity 1s ease; }

:scope:not([data-surface="tv"]) [data-slot="home.hero"]:has([data-part="hero.video"][data-state="playing"]) [data-part="mq.desc"] { grid-template-rows: 0fr; margin-bottom: 0; opacity: 0; }

:scope:not([data-surface="tv"]) [data-part="mq.synopsis"] { width: 576px; max-width: 100%; min-height: 0; line-height: 28px; }

:scope:not([data-surface="tv"]) [data-part="mq.play"], :scope:not([data-surface="tv"]) [data-part="mq.info"] { height: 48px; min-height: 48px !important; gap: 8px !important; padding: 8px 20px !important; border-radius: 9999px !important; font-size: 18px; font-weight: 500 !important; line-height: 24px; transition: background-color 0.25s cubic-bezier(0.4, 0, 0.68, 0.06), border-color 0.25s cubic-bezier(0.4, 0, 0.68, 0.06); }

:scope:not([data-surface="tv"]) [data-part="mq.play"] { background: #fff !important; color: #000 !important; }

:scope:not([data-surface="tv"]) [data-part="mq.play"]:hover { background: rgba(255, 255, 255, 0.75) !important; filter: none !important; }

:scope:not([data-surface="tv"]) [data-part="mq.info"] { background: rgba(128, 128, 128, 0.4) !important; color: #fff !important; }

:scope:not([data-surface="tv"]) [data-part="mq.info"]:hover { background: rgba(128, 128, 128, 0.25) !important; filter: none !important; }

:scope:not([data-surface="tv"]) [data-part="mq.play"] svg, :scope:not([data-surface="tv"]) [data-part="mq.info"] svg { width: 24px; height: 24px; }

:scope:not([data-surface="tv"]) [data-part="mq.callouts"] { margin: 0 40px 40px 0; }

:scope:not([data-surface="tv"]) [data-part="mq.callout"] { padding: 8px; border-radius: 8px; background: rgba(0, 0, 0, 0.5); color: #fff; line-height: 20px; }

:scope:not([data-surface="tv"]) [data-part="mq.callout-icon"] svg { width: 20px; height: 20px; }

:scope:not([data-surface="tv"]) [data-slot="home.hero"] [data-part="hero.edge"] { display: none !important; }

/* ── Rows: 24/500 headings at x = 60, 10 px over the track; 16:9 cards 237 × 133, radius 12, 8 apart. ── */
:scope:not([data-surface="tv"]) [data-part="row.header"] { margin-bottom: 0 !important; padding-left: 60px !important; padding-right: 60px !important; padding-bottom: 10px !important; }

:scope:not([data-surface="tv"]) [data-part="row.title"] { color: #fff; font-size: 24px !important; font-weight: 500 !important; line-height: 30px; letter-spacing: 0; }

:scope:not([data-surface="tv"]) [data-part="row.track"] { padding: 2px 60px !important; }

:scope:not([data-surface="tv"]) [data-part="row.step"] { top: 0 !important; bottom: 0 !important; height: auto !important; width: 40px !important; transform: none !important; border: 0 !important; border-radius: 0 !important; background: rgba(20, 20, 20, 0.5) !important; box-shadow: none !important; color: #fff !important; -webkit-backdrop-filter: none !important; backdrop-filter: none !important; }

:scope:not([data-surface="tv"]) [data-part="row.step"][data-dir="next"] { right: 0 !important; left: auto !important; }

:scope:not([data-surface="tv"]) [data-part="row.step"][data-dir="previous"] { left: 0 !important; }

:scope:not([data-surface="tv"]) [data-part="row.step"] svg { width: 32px; height: 32px; }

/* Boxart card: art cover, the title logo (or the title) bottom-left, a red ribbon centred on the bottom edge. */
[data-part="mq.box"] { border-radius: 12px; background: #2a2a2a; }

[data-part="mq.box-art"] img { transform: none !important; }

[data-part="mq.brand"] { width: 60%; padding: 0 0 22px 10px; }

[data-part="mq.brand-logo"] { max-height: 52px; }

[data-part="mq.brand-logo"] img { object-position: left bottom; filter: drop-shadow(0 1px 3px rgba(0, 0, 0, 0.6)); }

[data-part="mq.brand-title"] { line-height: 1.1; text-shadow: 0 1px 4px rgba(0, 0, 0, 0.85); }

[data-part="mq.ribbon"] { position: absolute !important; left: 50%; bottom: 0; z-index: 3; transform: translateX(-50%); padding: 3px 8px 2px; border-radius: 3px 3px 0 0; background: var(--mq-red); color: #fff; line-height: 13px; white-space: nowrap; }

[data-part="mq.runtime"], [data-part="mq.more"] { display: none !important; }

/* Continue Watching: a 2 px red progress line on #808080 under the art. */
[data-part="mq.cw-bar"] { min-height: 2px !important; height: 2px !important; margin-top: 6px; border-radius: 0 !important; background: #808080 !important; }

[data-part="mq.cw-bar"] > span { border-radius: 0 !important; background: var(--mq-red) !important; }

/* Ranked row: a 237 × 170 slot (the hover preview grows from the whole slot), the numeral in the left half
   under the 2:3 poster on the right half. */
[data-part="preview.anchor"] { height: 170px; }

[data-part="mq.rank"] { flex: 0 0 50%; justify-items: end; align-items: center; overflow: visible !important; }

[data-part="mq.rank-line"], [data-part="mq.rank-fill"] { margin-right: -6px; font-size: 230px !important; line-height: 170px; letter-spacing: -0.12em; white-space: nowrap; transform: scaleX(0.78); transform-origin: right center; }

/* Ten numerals: the row keeps its first ten titles. */
:scope:not([data-surface="tv"]) [data-slot="row"][data-role="trending"] [data-part="row.track"] > :nth-child(n+11) { display: none; }

[data-part="mq.rank-line"] { -webkit-text-stroke: 6px transparent; background-image: linear-gradient(rgba(255, 255, 255, 0.85), rgba(255, 255, 255, 0.1)); -webkit-background-clip: text; background-clip: text; color: transparent; }

[data-part="mq.rank-fill"] { color: #141414; }

[data-part="mq.top-poster"] { flex: 0 0 50%; z-index: 3 !important; border-radius: 4px; background: #2a2a2a; }

[data-part="mq.top-art"] img { transform: none !important; }

/* Placeholders: flat dark tiles in the card's shape (no shimmer). */
:scope:not([data-surface="tv"]) [data-part="row.skeleton"] { width: 237px !important; aspect-ratio: 16 / 9 !important; height: auto !important; border-radius: 12px !important; background: linear-gradient(#2a2a2a, #141414) !important; animation: none !important; }

:scope:not([data-surface="tv"]) [data-part="row.skeleton"]::after, :scope:not([data-surface="tv"]) [data-part="row.skeleton"]::before { display: none !important; }

/* ── Hover mini-modal: 1.5× the card, radius 6, #181818 info, round controls. ── */
[data-part="preview"][data-variant="expand"] { border-radius: 6px !important; background: #181818 !important; box-shadow: rgba(0, 0, 0, 0.75) 0 3px 10px !important; }

:scope:not([data-surface="tv"]) [data-part="preview.art"] > button { display: grid !important; place-items: center; top: 12px !important; right: 12px !important; width: 32px; height: 32px; padding: 0 !important; border: 1px solid rgba(255, 255, 255, 0.5) !important; border-radius: 50% !important; background: rgba(42, 42, 42, 0.6) !important; color: #fff !important; }

:scope:not([data-surface="tv"]) [data-part="preview.art"] > button svg { width: 16px; height: 16px; }

[data-part="preview.body"] { gap: 0 !important; padding: 16px !important; }

[data-part="preview.logo"] { left: 16px !important; bottom: 16px !important; max-width: 142px !important; max-height: 57px !important; }

[data-part="preview.title"] { left: 16px !important; bottom: 14px !important; font-size: 20px !important; font-weight: 700 !important; }

[data-part="preview.actions"] { height: 46px; gap: 8px !important; margin-bottom: 8px; }

[data-part="preview.action"] { width: 38px !important; height: 38px !important; border: 2px solid rgba(255, 255, 255, 0.5) !important; border-radius: 50% !important; background: rgba(42, 42, 42, 0.6) !important; color: #fff !important; }

[data-part="preview.action"]:hover { border-color: #fff !important; }

[data-part="preview.action"][data-action="play"] { width: 34px !important; height: 34px !important; border: 0 !important; background: #fff !important; color: #000 !important; }

[data-part="preview.action"][data-action="play"]:hover { background: rgba(255, 255, 255, 0.75) !important; }

[data-part="preview.action"] svg { width: 20px; height: 20px; }

[data-part="preview.meta"] { gap: 0 8px !important; margin-bottom: 8px; color: #bcbcbc !important; font-size: 16px !important; line-height: 24px; }

[data-part="preview.genres"] { gap: 0 8px !important; color: #fff !important; font-size: 16px !important; line-height: 24px; }

[data-part="preview.genres"] > [aria-hidden] { color: #646464 !important; }

/* ── Series page: a centred 850 px #181818 panel, radius 6, 32 px under the bar on a black page. ── */
:scope:not([data-surface="tv"]) [data-slot="page"]:has(> * [data-slot="detail"][data-layout="overlay"][data-variant="desktop"]), :scope:not([data-surface="tv"]) [data-slot="page"]:has([data-slot="detail"][data-layout="overlay"][data-variant="desktop"]) { background-color: #000; background-image: linear-gradient(90deg, #000 calc(50% - 425px), #181818 calc(50% - 425px), #181818 calc(50% + 425px), #000 calc(50% + 425px)); background-repeat: no-repeat; background-position: 0 calc(var(--theme-top-bar) + 132px); background-size: 100% 100%; }

:scope:not([data-surface="tv"]) [data-slot="detail"][data-layout="overlay"][data-variant="desktop"] { width: 850px !important; max-width: calc(100vw - 32px); min-height: 0 !important; margin: 32px auto 0; overflow: hidden; border-radius: 6px 6px 0 0; background: #181818; }

:scope:not([data-surface="tv"]) [data-slot="detail"][data-variant="desktop"] [data-part="detail.backdrop"] { bottom: auto !important; height: 479px !important; object-position: center top !important; }

:scope:not([data-surface="tv"]) [data-slot="detail"][data-variant="desktop"] [data-part="detail.video"] { bottom: auto !important; height: 479px !important; }

:scope:not([data-surface="tv"]) [data-slot="detail"][data-variant="desktop"] [data-part="detail.scrim"][data-dir="bottom"] { bottom: auto !important; height: 479px !important; background-image: linear-gradient(0deg, #181818 0%, rgba(24, 24, 24, 0) 45%) !important; }

:scope:not([data-surface="tv"]) [data-slot="detail"][data-variant="desktop"] [data-part="detail.scrim"][data-dir="left"] { display: none; }

:scope:not([data-surface="tv"]) [data-slot="detail"][data-variant="desktop"] [data-part="detail.body"] { display: grid !important; grid-template-columns: minmax(0, 481fr) minmax(0, 234fr); column-gap: 32px !important; row-gap: 0 !important; align-content: start; min-height: 0 !important; max-width: none !important; padding: 0 48px 32px !important; }

:scope:not([data-surface="tv"]) [data-slot="detail"][data-variant="desktop"] [data-part="detail.body"] > * { grid-column: 1; }

:scope:not([data-surface="tv"]) [data-slot="detail"][data-variant="desktop"] [data-part="detail.alt-title"],
:scope:not([data-surface="tv"]) [data-slot="detail"][data-variant="desktop"] [data-part="detail.studio"],
:scope:not([data-surface="tv"]) [data-slot="detail"][data-variant="desktop"] [data-part="detail.meta"] { display: none !important; }

:scope:not([data-surface="tv"]) [data-slot="detail"][data-variant="desktop"] [data-part="detail.title"] { grid-column: 1 / -1; grid-row: 1; display: flex; align-items: flex-end; min-height: 362px; margin: 0; font-size: 48px !important; font-weight: 700 !important; line-height: 1.05 !important; letter-spacing: -0.02em; text-shadow: none !important; filter: none !important; }

:scope:not([data-surface="tv"]) [data-slot="detail"] [data-part="detail.logo"] { max-width: 340px !important; max-height: 136px !important; object-fit: contain; object-position: left bottom; }

:scope:not([data-surface="tv"]) [data-slot="detail"][data-variant="desktop"] [data-part="detail.actions"] { grid-column: 1 / -1; grid-row: 2; gap: 8px !important; margin: 24px 0 48px; }

:scope:not([data-surface="tv"]) [data-slot="detail"][data-variant="desktop"] [data-part="detail.header"], :scope:not([data-surface="tv"]) [data-slot="detail"][data-variant="desktop"] [data-part="detail.header"] > *, :scope:not([data-surface="tv"]) [data-part="mq.dh"] { display: contents !important; }

:scope:not([data-surface="tv"]) [data-part="mq.dh-meta"] { grid-column: 1; grid-row: 3; align-self: start; flex-wrap: wrap; margin-bottom: 8px; color: #bcbcbc; line-height: 24px; }

:scope:not([data-surface="tv"]) [data-part="mq.dh-credits"] { grid-column: 2; grid-row: 3 / span 3; align-self: start; gap: 14px !important; }

[data-part="mq.hd"] { padding: 0 4px; border: 1px solid rgba(255, 255, 255, 0.4); border-radius: 3px; color: rgba(255, 255, 255, 0.9); font-size: 11.2px !important; line-height: 16px; }

[data-part="mq.dh-new"] { color: #46d369; }

[data-part="mq.credit"] { display: block !important; line-height: 20px; }

[data-part="mq.credit"] > * { display: inline !important; }

[data-part="mq.credit-label"] { color: #777; }

[data-part="mq.credit-value"] { color: #ddd; }

:scope:not([data-surface="tv"]) [data-slot="detail"][data-variant="desktop"] [data-part="detail.synopsis"] { grid-column: 1; grid-row: 4; -webkit-line-clamp: 8 !important; max-width: none !important; color: #fff !important; font-size: 16px !important; line-height: 26px !important; }

:scope:not([data-surface="tv"]) [data-slot="detail"][data-variant="desktop"] [data-part="detail.rating"] { grid-column: 1; grid-row: 5; }

/* Play: square-cornered, white, 45 px; Save as a 38 px round outline button. */
:scope:not([data-surface="tv"]) [data-slot="detail"] [data-part="button"][data-action="play"] { height: 45px; padding: 0 24px 0 20px !important; gap: 8px !important; border-radius: 4px !important; background: #fff !important; color: #000 !important; font-size: 16px !important; font-weight: 500 !important; }

:scope:not([data-surface="tv"]) [data-slot="detail"] [data-part="button"][data-action="play"]:hover { background: rgba(255, 255, 255, 0.75) !important; }

:scope:not([data-surface="tv"]) [data-slot="detail"] [data-part="button"][data-action="play"] svg { width: 23px; height: 23px; fill: currentColor; }

:scope:not([data-surface="tv"]) [data-slot="detail"] [data-part="button"][data-action="save"] { width: 38px !important; height: 38px !important; border: 2px solid rgba(255, 255, 255, 0.5) !important; border-radius: 50% !important; background: rgba(42, 42, 42, 0.6) !important; color: #fff !important; }

:scope:not([data-surface="tv"]) [data-slot="detail"] [data-part="button"][data-action="save"]:hover { border-color: #fff !important; }

:scope:not([data-surface="tv"]) [data-slot="detail"] [data-part="button"][data-action="save"] svg { width: 20px; height: 20px; }

:scope:not([data-surface="tv"]) [data-part="detail.mute"] { display: grid !important; place-items: center; width: 38px !important; height: 38px !important; padding: 0 !important; top: 389px !important; right: 48px !important; border: 2px solid rgba(255, 255, 255, 0.5) !important; border-radius: 50% !important; background: rgba(42, 42, 42, 0.6) !important; }

:scope:not([data-surface="tv"]) [data-part="detail.mute"] svg { width: 20px; height: 20px; }

:scope:not([data-surface="tv"]) [data-slot="detail"][data-variant="desktop"] [data-part="detail.title"] { transform-origin: left bottom; transition: transform 1s ease; }

:scope:not([data-surface="tv"]) [data-slot="detail"][data-variant="desktop"]:has([data-part="detail.video"][data-state="playing"]) [data-part="detail.title"] { transform: scale(0.65); }

/* The content under the panel's header: episodes and More Like This in the panel's 754 px column. */
:scope:not([data-surface="tv"]) [data-slot="detail.episodes"], :scope:not([data-surface="tv"]) [data-slot="detail.section"] { max-width: 754px; margin-left: auto !important; margin-right: auto !important; }

