:scope:not([data-surface="tv"]) [data-slot="search"] { padding-left: 60px !important; padding-right: 60px !important; }

:scope:not([data-surface="tv"]) [data-slot="search"] [data-part="search.field"] { flex: 0 0 400px; width: 400px; height: 56px; padding: 16px 53px 16px 48px !important; border: 1px solid rgba(255, 255, 255, 0.85) !important; border-radius: 4px !important; background: rgba(0, 0, 0, 0.75) url(data:image/svg+xml,%3Csvg%20xmlns=%27http://www.w3.org/2000/svg%27%20viewBox=%270%200%2024%2024%27%20fill=%27none%27%20stroke=%27white%27%20stroke-width=%272%27%20stroke-linecap=%27round%27%3E%3Ccircle%20cx=%2710.5%27%20cy=%2710.5%27%20r=%276.5%27/%3E%3Cpath%20d=%27m20%2020-4.5-4.5%27/%3E%3C/svg%3E) no-repeat 14px center / 24px 24px !important; color: #fff; font-size: 16px !important; }

:scope:not([data-surface="tv"]) [data-slot="search"] [data-part="search.filter"] { height: 36px; border: 1px solid rgba(255, 255, 255, 0.5) !important; border-radius: 9999px !important; background: transparent !important; color: #fff !important; font-size: 14px !important; font-weight: 500 !important; }

