:scope[data-surface="tv"] [data-slot="nav.top"] > [data-part="nav.item"] { order: 1; height: calc(var(--u) * 60); padding: 0 calc(var(--u) * 26) !important; border-radius: calc(var(--u) * 30) !important; background: transparent; color: rgba(255, 255, 255, 0.7) !important; font-size: calc(var(--u) * 24) !important; font-weight: 500 !important; line-height: 1; transition: background-color 0.2s, color 0.2s; }

:scope[data-surface="tv"] [data-slot="nav.top"] > [data-part="nav.item"]:not([data-dest="search"]) [data-part="nav.item.icon"] { display: none; }

