:scope[data-surface="tv"] [data-slot="nav.top"] > [data-part="nav.item"][data-dest="search"] { order: 0; width: calc(var(--u) * 64); height: calc(var(--u) * 64); margin-left: auto; padding: 0 !important; justify-content: center; border-radius: 50% !important; color: #fff !important; }

:scope[data-surface="tv"] [data-slot="nav.top"] > [data-part="nav.item"][data-dest="search"] [data-part="nav.item.label"] { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

:scope[data-surface="tv"] [data-slot="nav.top"] > [data-part="nav.item"] [data-part="nav.item.icon"] svg { width: calc(var(--u) * 30); height: calc(var(--u) * 30); }

:scope[data-surface="tv"] [data-slot="nav.top"] > [data-part="nav.action"] { order: 2; width: calc(var(--u) * 60) !important; height: calc(var(--u) * 60) !important; border-radius: 50% !important; background: transparent !important; color: rgba(255, 255, 255, 0.7) !important; }

:scope[data-surface="tv"] [data-slot="nav.top"] > [data-part="nav.action"][data-action="incognito"] { margin-left: auto; }

:scope[data-surface="tv"] [data-slot="nav.top"] > [data-part="nav.action"] svg { width: calc(var(--u) * 30); height: calc(var(--u) * 30); }

:scope[data-surface="tv"] [data-slot="nav.top"] > [data-part="nav.action"][data-action="account"] { order: -1; width: calc(var(--u) * 48) !important; height: calc(var(--u) * 48) !important; margin-right: calc(var(--u) * 24); border-radius: calc(var(--u) * 8) !important; }

:scope[data-surface="tv"] [data-slot="nav.top"] > [data-part="nav.action"][data-action="account"] img { width: calc(var(--u) * 48); height: calc(var(--u) * 48); border-radius: calc(var(--u) * 8); }

/* Home: the page takes a dark tint of the billboard's art and drops to black once focus enters the rows (1 s). */
:scope[data-surface="tv"] [data-slot="page"]:has([data-slot="home"]) { background-color: color-mix(in srgb, rgb(var(--hero-ambient-rgb, 48 51 68)) 32%, #000); transition: background-color 1s var(--mq-ease); }

