/* Billboard: an inset card 1782 × 764 at x = 69 under the bar, r 22; the copy at x = 98, its buttons 33 px
   above the card's bottom; the next row's title peeks at y ≈ 953. */
:scope[data-surface="tv"] [data-slot="home.hero"][data-variant="template"] { height: calc(var(--u) * 764) !important; min-height: 0 !important; margin: 0 calc(var(--u) * 69) calc(var(--u) * 48) !important; border-radius: calc(var(--u) * 22); }

:scope[data-surface="tv"] [data-slot="home.hero"][data-state="loading"] { background: rgba(255, 255, 255, 0.04) !important; }

