:scope[data-surface="tv"] [data-part="mq.copy"] { width: calc(var(--u) * 640); padding: 0 0 calc(var(--u) * 33) calc(var(--u) * 29) !important; }

:scope[data-surface="tv"] [data-part="mq.eyebrow"] { margin-bottom: calc(var(--u) * 10); font-size: calc(var(--u) * 14) !important; letter-spacing: 0.2em; text-transform: uppercase; }

:scope[data-surface="tv"] [data-part="mq.logo"] { width: calc(var(--u) * 420) !important; height: calc(var(--u) * 120); margin-bottom: calc(var(--u) * 16); }

:scope[data-surface="tv"] [data-part="mq.logo"] img { object-position: left bottom; }

:scope[data-surface="tv"] [data-part="mq.title"] { margin-bottom: calc(var(--u) * 14); font-size: calc(var(--u) * 56) !important; line-height: 1.05; letter-spacing: -0.02em; text-shadow: none !important; }

:scope[data-surface="tv"] [data-part="mq.attrs"] { gap: calc(var(--u) * 10) !important; margin-bottom: calc(var(--u) * 10); color: #fff; }

:scope[data-surface="tv"] [data-part="mq.attrs"] * { font-size: calc(var(--u) * 22) !important; line-height: calc(var(--u) * 30); }

