:scope[data-surface="tv"] [data-part="mq.attrs"] [data-part="mq.age"] { height: calc(var(--u) * 28); padding: 0 calc(var(--u) * 6); font-size: calc(var(--u) * 16) !important; }

:scope[data-surface="tv"] [data-part="mq.synopsis"] { max-width: calc(var(--u) * 560); margin-bottom: calc(var(--u) * 26); color: rgba(255, 255, 255, 0.9) !important; font-size: calc(var(--u) * 24) !important; line-height: calc(var(--u) * 34); }

:scope[data-surface="tv"] [data-part="mq.actions"] { gap: calc(var(--u) * 12) !important; overflow: visible !important; }

:scope[data-surface="tv"] :is([data-part="mq.play"], [data-part="mq.info"]) { height: calc(var(--u) * 76); min-height: 0 !important; gap: calc(var(--u) * 12) !important; padding: 0 calc(var(--u) * 36) 0 calc(var(--u) * 30) !important; border-radius: 9999px !important; background: rgba(255, 255, 255, 0.2) !important; color: #fff !important; font-size: calc(var(--u) * 26) !important; font-weight: 500 !important; filter: none !important; transition: background-color 0.2s, color 0.2s; }

:scope[data-surface="tv"] :is([data-part="mq.play"], [data-part="mq.info"]) svg { width: calc(var(--u) * 28); height: calc(var(--u) * 28); }

:scope[data-surface="tv"] :is([data-part="mq.play"], [data-part="mq.info"]):is(:focus, :focus-visible) { outline: none !important; box-shadow: none !important; background: #fff !important; color: #000 !important; }

:scope[data-surface="tv"] [data-part="mq.callouts"] { margin: 0 calc(var(--u) * 40) calc(var(--u) * 50) 0; }

:scope[data-surface="tv"] [data-part="mq.callout"] { display: inline-flex; align-items: center; height: calc(var(--u) * 50); padding: 0 calc(var(--u) * 24); border-radius: 9999px; background: rgba(0, 0, 0, 0.7); color: #fff; font-size: calc(var(--u) * 22) !important; }

:scope[data-surface="tv"] [data-slot="home.hero"] :is([data-part="hero.edge"], [data-part="hero.indicator"]) { display: none !important; }

/* Rows: 32/700 titles at x = 70 (dimmed to #6C6B70 until the row has focus); 312 × 507 boxart 18 apart.
   The focused tile becomes 905 × 508 key art with a 4 px white stroke, anchored in the first column;
   the focused row snaps 137 px down, under the bar. */
:scope[data-surface="tv"] [data-slot="row"] { scroll-margin-top: calc(var(--u) * 130); margin-bottom: calc(var(--u) * 108) !important; }

:scope[data-surface="tv"] [data-part="row.header"] { margin-bottom: 0 !important; padding: 0 calc(var(--u) * 70) calc(var(--u) * 18) !important; }

:scope[data-surface="tv"] [data-part="row.title"] { color: #6c6b70; font-size: calc(var(--u) * 32) !important; font-weight: 700 !important; line-height: calc(var(--u) * 40); transition: color 0.25s; }

:scope[data-surface="tv"] [data-slot="row"]:focus-within [data-part="row.title"] { color: #fff; }

:scope[data-surface="tv"] [data-part="row.track"] { gap: calc(var(--u) * 18) !important; padding: 0 calc(100vw - var(--u) * 975) 0 calc(var(--u) * 70) !important; }

:scope[data-surface="tv"] [data-part="row.step"] { display: none !important; }

:scope[data-surface="tv"] [data-part="card"]:has([data-part="mq.tile"]) { width: calc(var(--u) * 312) !important; transition: width 0.65s var(--mq-ease); }

:scope[data-surface="tv"] [data-row-focus="anchor"] [data-part="card"]:has([data-part="mq.tile"]):focus-within { width: calc(var(--u) * 905) !important; }

